package dev.zomboid.hordes;
import java.util.*;
/** One bounded local snapshot per second. No chunk loading and no per-zombie tick loop. */
public final class Population47 {
 static final Map<Object,View> CACHE=new WeakHashMap<>();static boolean warned;
 static Object c(Object o,String n,Object...a){return ZoneReflection.call(o,n,a);}static double coord(Object o,String a){return ((Number)c(o,"get"+a)).doubleValue();}static int chunk(Object o,String a){return (int)Math.floor(coord(o,a)/16);}
 static boolean eligible(Object p){return Boolean.TRUE.equals(c(p,"isAlive"))&&!Boolean.TRUE.equals(c(p,"isCreative"))&&!Boolean.TRUE.equals(c(p,"isSpectator"));}
 static long time(Object w){return ((Number)c(w,"getGameTime")).longValue();}
 static List<Object> players(Object world){List<Object> list=new ArrayList<>();for(Object p:(List<?>)c(world,"players"))if(eligible(p))list.add(p);return list;}
 static boolean zombie(Object n){return Boolean.TRUE.equals(c(n,"isAlive"))&&Boolean.TRUE.equals(c(ZombieIndividual.class,"supported",n));}
 static View view(Object world){long now=time(world);View old=CACHE.get(world);List<Object> ps=players(world);if(old!=null&&now>=old.at&&now-old.at<20&&matches(old,ps))return old;Map<Object,Object> unique=new HashMap<>();for(Object p:ps){int x=chunk(p,"X"),z=chunk(p,"Z");Object box;try{box=ZoneReflection.type("net.minecraft.world.phys.AABB").getConstructor(double.class,double.class,double.class,double.class,double.class,double.class).newInstance((x-1)*16.,((Number)c(world,"getMinBuildHeight")).doubleValue(),(z-1)*16.,(x+2)*16.,((Number)c(world,"getMaxBuildHeight")).doubleValue(),(z+2)*16.);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}for(Object e:(List<?>)c(world,"getEntitiesOfClass",ZoneReflection.type("net.minecraft.world.entity.Mob"),box))if(zombie(e))unique.put(c(e,"getUUID"),e);}
  View v=new View(now,ps,new ArrayList<>(unique.values()));CACHE.put(world,v);return v;
 }
 static int count(View v,Object player){int px=chunk(player,"X"),pz=chunk(player,"Z"),n=0;for(Object e:v.entities)if(zombie(e)&&AmbientSettings47.window(chunk(e,"X"),chunk(e,"Z"),px,pz))n++;return n;}
 static boolean room(View v,Object e){int x=chunk(e,"X"),z=chunk(e,"Z"),close=0;for(Object p:v.players)if(AmbientSettings47.window(x,z,chunk(p,"X"),chunk(p,"Z"))&&count(v,p)>=AmbientSettings47.total())return false;for(Object other:v.entities){if(other==e||!zombie(other))continue;double dx=coord(e,"X")-coord(other,"X"),dy=coord(e,"Y")-coord(other,"Y"),dz=coord(e,"Z")-coord(other,"Z");if(dx*dx+dy*dy+dz*dz<=256&&++close>=AmbientSettings47.group())return false;}return true;}
 public static void join(Object event){Object world=c(event,"getLevel");if(Boolean.TRUE.equals(c(world,"isClientSide"))||Boolean.TRUE.equals(c(event,"loadedFromDisk")))return;Object e=c(event,"getEntity");if(!zombie(e))return;for(Class<?>t=e.getClass();t!=null;t=t.getSuperclass())if(t.getSimpleName().equals("PlayerZombie"))return;try{View v=view(world);int x=chunk(e,"X"),z=chunk(e,"Z");if(v.players.isEmpty())return;if(v.players.stream().noneMatch(p->AmbientSettings47.window(x,z,chunk(p,"X"),chunk(p,"Z")))){c(event,"setCanceled",true);return;}if(!room(v,e)){c(event,"setCanceled",true);return;}if(v.entities.stream().noneMatch(o->c(o,"getUUID").equals(c(e,"getUUID"))))v.entities.add(e);}catch(RuntimeException ex){warn(ex);}}
 public static int populate(Object world,Object data,List<Object> supplied,long now){if(now%100!=0||ZoneReserve.paused(world))return 0;try{View v=view(world);int made=0;int[] budget={48};for(Object p:supplied){if(!eligible(p))continue;int target=AmbientSettings47.desired(WorldTuning.get("densidad"),AmbientSettings47.total(),Heat47.value(p));if(count(v,p)>=target)continue;List<int[]> chunks=new ArrayList<>();int px=chunk(p,"X"),pz=chunk(p,"Z");for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)chunks.add(new int[]{px+dx,pz+dz});Collections.shuffle(chunks,new Random(now^c(p,"getUUID").hashCode()));int personal=0;for(int[] cell:chunks){if(made>=6||personal>=3||budget[0]<=0||count(v,p)>=target)break;if(ChunkPopulation.spawnInChunk(world,supplied,cell[0],cell[1],budget)){made++;personal++;}}}return made;}catch(RuntimeException ex){warn(ex);return 0;}}
 static void warn(Exception e){if(!warned){warned=true;System.getLogger("Ambiente47").log(System.Logger.Level.ERROR,"Población local: se conserva la población existente",e);}}
 public static void clear(Object event){CACHE.clear();Heat47.STATES.clear();warned=false;}
 static long key(Object p){return ((long)chunk(p,"X")<<32)^(chunk(p,"Z")&0xffffffffL);}
 static boolean matches(View v,List<Object>ps){if(v.chunks.size()!=ps.size())return false;for(Object p:ps)if(!Objects.equals(v.chunks.get(c(p,"getUUID")),key(p)))return false;return true;}
 static Map<Object,Long> signature(List<Object>ps){Map<Object,Long>m=new HashMap<>();for(Object p:ps)m.put(c(p,"getUUID"),key(p));return m;}
 static final class View {final long at;final List<Object>players,entities;final Map<Object,Long> chunks;View(long t,List<Object>p,List<Object>e){at=t;players=p;entities=e;chunks=signature(p);}}
}
